			this.blocks.get(i++).getBinData().flip(); // 修改limit，保证刚刚被写入的数据在恰好在有效范围内

			offset += l;
			l = Math.min(Config.BLOCK_SIZE, content.length() - offset);
		}

		// 内容大小小于写入的块，将之后的块清空
		while (i < startBlockId + length) {
			this.blocks.get(i).wipe();
			this.blocks.get(i++).getBinData().flip();
		}
	}

