                barrier.awaitOpenUninterruptibly();
            }
        };
        t.start();
        t.join();

        assertEquals(0, t.getExecutionTimeMs());
    }

    @Test
    public void whenStartClosedAndOpened_thenReturnsImmediately() throws InterruptedException {
        barrier = new VetoCommitBarrier();

        TestThread t = new TestThread() {
            @Override
            public void doRun() throws Exception {
                barrier.awaitOpenUninterruptibly();
            }
        };
        t.start();

        // give the thread some time to start
        Thread.sleep(10);
        barrier.open();
        t.join();

        assertEquals(0, t.getExecutionTimeMs());
    }

