		assertEquals(-2, this.t.iy());
		assertEquals(0, this.t.iz());
		IntegerProperty property = this.t.zProperty();
		property.set(345);
		assertEquals(1, this.t.ix());
		assertEquals(-2, this.t.iy());
		assertEquals(345, this.t.iz());
	}

}

