        assertEquals("4", expected, result);

        //

        expected = Charset.forName("cp1250");

        result   = manager.decodeValue(charset, manager.encodeValue(expected, false));

        assertEquals("5", expected, result);

        //

        expected = null;

        result   = manager.decodeValue(charset, manager.encodeValue(expected, false));

        assertEquals("6", expected, result);

    }





