	/**

	* This method calculates the probability density function at a given value.

	* @param x the value at which to calculate the pdf

	* @return the pdf at x

	*/

	public double pdf(double x){

		if(x < order || x > populationSize - (sampleSize - order))

			return 0;

		else{

			double num = Combinatorics.combinations(x - 1, order - 1) *

						Combinatorics.combinations(populationSize - x, sampleSize - order);

			double den = Combinatorics.combinations(populationSize, sampleSize);

			return num / den;

		}

	}



