public class CnsOpenDirResponse extends CnsResponse {

    private LFCFile[] files;

    public CnsOpenDirResponse() {
        super(OpType.CNS_OPENDIR);
    }

    @Override
    public void readFrom(DataInputStream dis) throws IOException, LFCException {
        int count = dis.readInt();
        files = new LFCFile[count];
        for (int i = 0; i < count; i++) {
            files[i] = new LFCFile();
            files[i].readFrom(dis);
        }
    }

