            return;
        }

        if(node._type == ONodeType.Array)
        {
            writer.WriteArrayStart();
            for(ONode v:node._array.elements)
                writeJson(v,writer);
            writer.WriteArrayEnd();
            return;
        }
    }

    protected static void writeXml(ONodeBase node, XmlWriter writer)
    {
        if(node._type == ONodeType.Null)
