            {
                writer.WriteNodeStart(kv.getKey());
                writeXml(kv.getValue(), writer);
                writer.WriteNodeEnd(kv.getKey());
            }
            return;
        }

        if(node._type == ONodeType.Array)
        {
            for(ONode v:node._array.elements) {
                writer.WriteNodeStart("item");
                writeXml(v, writer);
                writer.WriteNodeEnd("item");
            }
            return;
        }
    }
